std::optional<std::size_t> vaoff(const PeInfo&pe,std::uint64_t va,std::size_t n){if(!pe.valid||va<pe.image_base)return{};auto r=va-pe.image_base;if(r<pe.headers_size&&r<n)return std::size_t(r);for(const auto&s:pe.sections){auto span=std::max(s.vsize,s.raw_size);if(r>=s.rva&&r<std::uint64_t(s.rva)+span){auto delta=r-s.rva;if(delta>=s.raw_size)return{};auto o=std::uint64_t(s.raw_offset)+delta;if(o<n)return std::size_t(o);}}return{};}
