        if(offset&&!shift&&z.ins.mnemonic==ZYDIS_MNEMONIC_ADD&&oc>=2&&zydis_reg(z.ops[0],ZYDIS_REGISTER_RAX)&&z.ops[1].type==ZYDIS_OPERAND_TYPE_IMMEDIATE&&!z.ops[1].imm.is_relative&&z.ops[1].imm.value.u>0&&z.ops[1].imm.value.u<=0x40)pre_shift_bias=z.ops[1].imm.value.u;
        if(z.ins.mnemonic==ZYDIS_MNEMONIC_SHL&&oc>=2&&zydis_reg(z.ops[0],ZYDIS_REGISTER_RAX)&&zydis_imm(z.ops[1],4)){shift=true;if(pre_shift_bias){base=static_cast<std::uint32_t>(pre_shift_bias<<4);base_add=true;}}
        if(shift&&z.ins.mnemonic==ZYDIS_MNEMONIC_ADD&&oc>=2&&zydis_reg(z.ops[0],ZYDIS_REGISTER_RAX)&&z.ops[1].type==ZYDIS_OPERAND_TYPE_IMMEDIATE&&!z.ops[1].imm.is_relative&&z.ops[1].imm.value.u>=0x100&&z.ops[1].imm.value.u<=0x300){base=static_cast<std::uint32_t>(z.ops[1].imm.value.u);base_add=true;}
        if(base_add&&z.ins.mnemonic==ZYDIS_MNEMONIC_ADD&&oc>=2&&zydis_reg(z.ops[0],ZYDIS_REGISTER_RAX)&&((z.ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER&&ZydisRegisterGetWidth(ZYDIS_MACHINE_MODE_LONG_64,z.ops[1].reg.value)==64)||z.ops[1].type==ZYDIS_OPERAND_TYPE_MEMORY))class_add=true;
