        auto tp=dp;auto tn=tp.filename().string();const std::string ds=".unity-dispatch-calls.csv";if(tn.size()>=ds.size()&&tn.compare(tn.size()-ds.size(),ds.size(),ds)==0)tn.replace(tn.size()-ds.size(),ds.size(),".unity-dispatch-targets.csv");else tn += ".targets.csv";tp=tp.parent_path()/tn;
        std::map<std::tuple<std::int32_t,std::int32_t,std::uint32_t>,std::uint32_t> set_ids;for(const auto&x:dispatch_sites)set_ids.emplace(std::make_tuple(x.receiver_type_definition_index,x.interface_type_definition_index,x.slot),0);std::uint32_t next_set=0;for(auto&[key,id]:set_ids){(void)key;id=next_set++;}
        std::ofstream df(dp,std::ios::binary),tf(tp,std::ios::binary);
