            tf<<"candidate_set_id,candidate_scope,receiver_type_definition_index,receiver_type,interface_type_definition_index,interface_type,dispatch_slot,candidate_index,method_index,method_rva,generic_index,receiver_type_count,method\n";
            for(const auto&[key,id]:set_ids){const auto receiver=std::get<0>(key);const auto iface=std::get<1>(key);const auto slot=std::get<2>(key);const auto&candidates=collect_dispatch_candidates(slot,iface,receiver);const auto scope=receiver>=0?"metadata_exact_receiver":iface>=0?"metadata_interface_implementors":"metadata_global_slot";for(std::size_t i=0;i<candidates.size();++i){const auto&c=candidates[i];tf<<id<<','<<csvq(scope)<<',';if(receiver>=0)tf<<receiver;tf<<',';if(receiver>=0&&static_cast<std::size_t>(receiver)<u.types.size())tf<<csvq(u.types[static_cast<std::size_t>(receiver)].full_name);tf<<',';if(iface>=0)tf<<iface;tf<<',';if(iface>=0&&static_cast<std::size_t>(iface)<u.types.size())tf<<csvq(u.types[static_cast<std::size_t>(iface)].full_name);tf<<','<<slot<<','<<i<<','<<c.method_index<<',';if(c.method_rva)tf<<"0x"<<std::hex<<c.method_rva<<std::dec;tf<<',';if(c.generic_index>=0)tf<<c.generic_index;tf<<','<<c.receiver_type_count<<','<<csvq(c.method)<<"\n";++r.dispatch_candidate_row_count;}}
